 ability=read(ROOT/'diagnostics/discriminator_ability.csv');metrics=read(ROOT/'results/mcljcv/equal_rate_summary.csv');grad=read(ROOT/'diagnostics/matched_gradient_windows.csv');overlap=load(ROOT/'audits/overlap_integrity.json');diag=load(ROOT/'audits/diagnostic_integrity.json');ev=load(ROOT/'audits/evaluation_integrity.json');params=read(ROOT/'diagnostics/parameter_changes.csv');rec=read(ROOT/'diagnostics/reconstruction_changes.csv');components=read(ROOT/'results/mcljcv/fid_decomposition_equal_rate.csv');probe=read(ROOT/'diagnostics/image_sensitivity.csv')
 normal=[r for r in ability if int(r['step'])==1000 and r['reconstruction_panel']=='fixed' and r.get('QP','all')=='all'];learning=[dict(domain=r['domain'],panel=r['panel_type'],top1=float(r['real_content_top1']),majority=float(r['GT_majority_top1']),top5=float(r['real_content_top5']),majority_top5=float(r['GT_majority_top5']),AUROC=float(r['AUROC_fake_from_frame_mean_p_fake']),CE_real=float(r['CE_real']),label_frequency_entropy=float(r['GT_frequency_entropy'])) for r in normal]
 learned=all(r['top1']>r['majority'] and r['top5']>r['majority_top5'] for r in learning);response=[r for r in probe if int(r['checkpoint'])==1000 and r['condition']=='matched' and r['image']=='reconstruction'];response_ce=statistics.mean(float(r['delta_CE_content']) for r in response);response_pf=statistics.mean(float(r['delta_p_fake']) for r in response);mean_mae=statistics.mean(float(r['reconstruction_MAE_vs_B1']) for r in rec if int(r['step'])==1000)
