   metric_decisions.append(dict(method=method,reference=reference,available=available,all_three_perceptual_nonincrease=available and all(differences[k]<=0 for k in ('LPIPS','DISTS','FloLPIPS')),FID_higher=available and differences['FID']>0,four_metric_nonincrease=available and all(v<=0 for v in differences.values()),signed_deltas=differences,diagnostic_mean_delta_D_mu=mean_mu,diagnostic_mean_delta_D_cov=mean_cov))
